---ShowPanel
---展示面板
---@param data table @ responseData 服务器返回数据
function UIBattleEndRightPanel:ShowPanel(data)
    self.showData = data
    --printInfo(table.toString(data, "PanelData"))
    local questId = UIBattlingDataMgr:GetQuestId()
    local showType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    local PassState = data.isPassed
    self:ShowType(showType, PassState)
end

---ShowType
--- Panel展示类型
---@param showType Constants.IDType 21-26
---@param passState integer @ 1 or 0
function UIBattleEndRightPanel:ShowType(showType, passState)
    if showType == Constants.IDType.QuestMain then
        self:ShowElementOfGameStory(passState)
    elseif showType == Constants.IDType.QuestCoinsCopy or
            showType == Constants.IDType.QuestExpCopy or
            showType == Constants.IDType.QuestPrimaryEquipCopy or
            showType == Constants.IDType.QuestUpStarCopy
    then
        self:ShowElementOfDailyQuest(passState, showType)
    elseif showType == Constants.IDType.QuestMaze then
        self:ShowElementOfMaze(passState)
    elseif showType == Constants.IDType.QuestGachaCoin
            or showType == Constants.IDType.QuestGachaCoinChallenge then
        self:ShowElementOfCallCopyLevel()
    elseif showType == Constants.IDType.QuestTrail then
        self:ShowElementOfTrial()
    elseif showType == Constants.IDType.QuestWorldBoss then
        self:ShowElementOfWorldBoss()
    elseif showType == Constants.IDType.QuestSeniorEquipCopy then
        self:ShowElementOfQuestSeniorEquipCopy(passState)
    else
        if passState then
            --- Title 任务完成
            self.Txt_MissionCompletedState.text = localize((checkInt(passState) == 1) and "任务完成" or "任务失败")
        end
        --- 奖励列表
        self:SetRewardList()
    end
end

---ShowElementOfCallCopyLevel
---展示假想实战结算元素
function UIBattleEndRightPanel:ShowElementOfCallCopyLevel()
    KTool.SetActive(self.Root_VirtualTrainingInfo.gameObject, true)
    --- Boss 头像
    local questId = checkNumber(self.showData.questId)
    local questVo = QuestConfMgr:GetQuestVoById(questId)
    if not IsNull(questVo) then
        local monster = checkNumber(questVo.monsterShow)
        local bossVo = CardConfMgr:GetInstance():GetMonsterTypeVoById(checkNumber(monster))
        if bossVo then
            local skinId = bossVo.skinId
            local skinData = UIBattlingTools.GetCardSkinDataBySkinId(skinId)
            if skinData then
                self.Img_BossHead:LoadSprite(skinData.buffHead)
            end
        end
    end
    --- Boss 等级
    local defLv = self.showData.response.copyLevel or checkNumber(GCQUtils.GetHomeDojo().copyLevel)
    if checkInt(defLv) >= 10 then
        KTool.SetActive(self.Txt_Max.gameObject, true)
    else
        KTool.SetActive(self.Txt_Lv.gameObject, true)
        self.Txt_Lv.text = defLv
    end
    --- Boss 血条 Process
    if IsNull(self.showData.response.bossHpPercent) then
        KTool.SetActive(self.PrecessSlider.gameObject, false)
        KTool.SetActive(self.Txt_DamageValue.gameObject, false)
    else
        local bossHpLast = checkNumber(self.showData.response.bossHpPercent) <= 0 and 0 or self.showData.response.bossHpPercent
        self.PrecessSlider.value = checkNumber(bossHpLast)
        --- Boss 血条 Text
        local valueEx = GCQUtils.GetHomeDojo().bossHpPercent
        local damageValue = Mathf.Floor((valueEx - bossHpLast) * 10000) * 0.01
        self.Txt_DamageValue.text = localize("<size=24>本次造成伤害</size> _Num_%", { _Num_ = string.format("%0.2f", damageValue) })
    end
    --- 奖励列表
    local rewardsList = self.showData.response.rewards
    if IsNull(rewardsList) or #rewardsList <= 0 then
        if IsNull(self.showData.response.bossHpPercent) then
            -- 挑战
            KTool.SetActive(self.Root_MissionRewardsList.gameObject, false)
        else
            KTool.SetActive(self.Root_MissionRewardsList.gameObject, true)
            KTool.SetActive(self.Root_RewardItems.gameObject, false)
            self:SetSpecialDesc()
        end
    else
        self:SetRewardList()
    end
end

function UIBattleEndRightPanel:SetSpecialDesc()
    local copyLVEx = checkNumber(GCQUtils.GetHomeDojo().copyLevel)
    local copyLVAfter = checkNumber(self.showData.response.copyLevel)
    if copyLVEx == copyLVAfter then
        KTool.SetActive(self.Txt_SpecialDes.gameObject, true)
        local copyRewardsPlayerHad = checkNumber(GCQUtils.GetHomeDojo().goodsSum)
        local valueRewardsMax = checkNumber(GCQUtils.GetGachaCoinMaxByLevel(copyLVAfter))
        self.Txt_SpecialDes.text = copyRewardsPlayerHad >= valueRewardsMax
                and localize("本周可获得奖励已达到上限")
                or localize("未达成下一阶段奖励的伤害要求")
    else
        -- print("奖励列表为空 任务难度等级太一致 等级原: %d  等级现: %d", copyLVEx, copyLVAfter)
    end
end

---ShowElementOfQuestSeniorEquipCopy
---高级装备本展示
---@param passState number
function UIBattleEndRightPanel:ShowElementOfQuestSeniorEquipCopy(passState)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.showData.questId)
    local questName = questVo.name -- 副本名
    if checkInt(passState) == 1 then
        local transTxt = self.Root_FastRelief:Find("TxtNumber")
        local meshTxt
        if transTxt then
            meshTxt = transTxt:GetComponent(typeof(TextMeshProUGUI))
        end
        local pointType = questVo.pointType -- 点数类型
        local typeVo = CfUtils.GetCfVo(AutoIds.IdSetting843, "QuestSeniorEquipBattleTypeVo", pointType)
        local rewardValue = typeVo.rewardCost
        if meshTxt and checkNumber(rewardValue) > 0 then
            meshTxt.text = tostring(rewardValue)
        end
        KTool.SetActive(self.Root_FastRelief.gameObject, checkNumber(rewardValue) > 0)
    end
    --- Title 任务完成
    self.Txt_MissionCompletedState.text = checkInt(passState) == 1
            and localize("任务完成")
            or localize("任务失败")
    KTool.SetActive(self.Txt_MissionName.gameObject, true)
    self.Txt_MissionName.text = questName -- 副本名
    self:SetRewardList()
end

---ShowElementOfWorldBoss
---世界 Boss 展示元素
function UIBattleEndRightPanel:ShowElementOfWorldBoss()
    KTool.SetActive(self.Root_WorldBoss.gameObject, true)
    local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
    local isOpen = worldBossComponent:IsOpen()
    if not isOpen then
        --- 在结算时 活动关闭时的处理
        local rootTxtHistory = self.Root_WorldBoss:Find("TxtHistory")
        local rootTxtNow = self.Root_WorldBoss:Find("TxtNow")
        KTool.SetActive(rootTxtHistory.gameObject, false)
        KTool.SetActive(rootTxtNow.gameObject, false)
        local transTxtQuestIsLocked = self.Root_WorldBoss:Find("TxtQuestLocked")
        if transTxtQuestIsLocked then
            KTool.SetActive(transTxtQuestIsLocked.gameObject, true)
        end
    else
        --- 正常处理
        local dataResponse = self.showData.response
        local oldMyRankInfo = dataResponse.oldMyRankInfo -- 返回数据 历史
        local newMyRankInfo = dataResponse.newMyRankInfo -- 返回数据 当前
        local transTxtHistory = self.Root_WorldBoss:Find("TxtHistory/TxtNumber")
        local transTxtNow = self.Root_WorldBoss:Find("TxtNow/TxtNumber")
        local txtHistory
        if transTxtHistory then
            txtHistory = transTxtHistory:GetComponent(typeof(TextMeshProUGUI))
        end
        if txtHistory then
            txtHistory.text = string.isEmpty(oldMyRankInfo.hurt) and "--" or checkNumber(oldMyRankInfo.hurt)
        end
        local txtNow
        if transTxtNow then
            txtNow = transTxtNow:GetComponent(typeof(TextMeshProUGUI))
        end
        if txtNow then
            txtNow.text = string.isEmpty(newMyRankInfo.hurt) and "--" or checkString(newMyRankInfo.hurt)
        end
        local valueOld = checkNumber(oldMyRankInfo.hurt)
        local valueNew = checkNumber(newMyRankInfo.hurt)
        if valueNew > 0 and valueNew > valueOld then
            local imgUp = transTxtNow.transform:Find("ImgUP")
            if imgUp then
                KTool.SetActive(imgUp.gameObject, true)
            end
        end
        txtNow.color = XLuaUtils.HexToColor((valueNew > 0 and valueNew > valueOld) and '#c15151' or '#343434')
    end
end

---ShowElementOfTrial
---试炼结算
function UIBattleEndRightPanel:ShowElementOfTrial()
    KTool.SetActive(self.Root_TrialInfo.gameObject, true)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.showData.questId)
    if not IsNull(questVo) then
        KTool.SetActive(self.Txt_MissionName.gameObject, true)
        self.Txt_MissionName.text = questVo.name
    end
    if checkInt(self.showData.response.score) > 0 then
        KTool.SetActive(self.Txt_Score.gameObject, true)
        self.Txt_ScoreTitle.text = localize("裁判评分")
        self.Txt_Score.text = tostring(math.floor(checkNumber(self.showData.response.score)))
        self.Txt_MissionCompletedState.text = localize("到此为止!")
    else
        KTool.SetActive(self.Img_NoScore.gameObject, true)
        self.Txt_ScoreTitle.text = localize("裁判拒绝评分")
        self.Txt_MissionCompletedState.text = localize("竟然放弃挑战!?")
    end
end

