---SetAllQuestFinishedRewardState
---设置 三星奖励
function UIBattleEndRightPanel:SetAllQuestFinishedRewardState()
    if isSet(self.showData.response, "starReward") and table.count(self.showData.response.starReward) > 0 then
        KTool.SetActive(self.Root_RewardOfMissionFinished.gameObject, true)
        local starRewardList = self.showData.response.starReward
        self:DataSort(starRewardList, 1, #starRewardList)
        self.starRewardList = starRewardList
        --- 设置 三星奖励 背景
        self:SetStarRewardBGState(#self.starRewardList)
        --- 设置 三星奖励 列表
        GameUtils.ReloadData(self.LoopListOfStarRewards, #self.starRewardList)
        --- 设置 三星奖励 是否开启滑动
        self:SetStarRewardSVState(#self.starRewardList)
    else
        KTool.SetActive(self.Root_RewardOfMissionFinished.gameObject, false)
    end
end

---SetRewardList
---设置奖励列表
---@param questType Constants.IDType
function UIBattleEndRightPanel:SetRewardList(questType)
    if IsNull(self.showData.response) then return end -- 对服务器返回数据判空
    local rewards = self.showData.response.rewards
    if rewards and table.count(rewards) > 0 then
        KTool.SetActive(self.Root_MissionRewardsList.gameObject, true)
        ---迷宫特殊 构造一个迷宫币奖励
        if checkNumber(questType) == Constants.IDType.QuestMaze and checkNumber(self.showData.response.coin) > 0 then
            local t = {
                goodsId = Constants.Currency.MazeCurrency,
                num = checkNumber(self.showData.response.coin)
            }
            table.insert(rewards, t)
        elseif (checkNumber(questType) == Constants.IDType.QuestCoinsCopy or checkNumber(questType) == Constants.IDType.QuestExpCopy or checkNumber(questType) == Constants.IDType.QuestUpStarCopy) and
                checkNumber(self.showData.response.energyPoint) > 0 then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.showData.questId)
            local itemId = self:GetItemID(vo.type)
            local valueItem = vo.energy or -999
            table.insert(rewards, {
                goodsId = itemId,
                num = valueItem,
            })
        end
        self:DataSort(rewards, 1, #rewards)
        self.rewardList = rewards
        GameUtils.ReloadData(self.Root_MissionRewardsList, #self.rewardList)
    else
        KTool.SetActive(self.Root_MissionRewardsList.gameObject, false)
    end
end

function UIBattleEndRightPanel:GetItemID(type)
    local dailyTypeVo = CfUtils.GetCfVo(AutoIds.IdSetting310, "DailyTypeVo", type)
    return dailyTypeVo.energyPointItem
end

---OnGetItemByIndex
---道具列表
---@param gridView SuperScrollView.LoopGridView
---@param index integer
function UIBattleEndRightPanel:OnGetItemByIndex(gridView, index)
    if index < 0 then return end
    local cell = gridView:NewListViewItem(GoodsNodePrefabName)
    local reScale = cell.gameObject:GetComponent(typeof(ReverseScale))
    reScale:ResetScale()
    local goodNodeMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)
    if not IsNull(goodNodeMB) then
        if IsNull(goodNodeMB.Env) then
            goodNodeMB:Init()
        end
        ---@type GoodNodeMB
        local env = goodNodeMB.Env
        local item = self.rewardList[index + 1]
        local num = self:CheckGoodsIdForSignNum(item.goodsId, item.num)
        if not IsNull(num) then
            num = string.format("x%s", math.abs(num))
            env:Reload({ goodsId = item.goodsId, isShowNo = true, text = tostring(num), dojo = item.playerEquipment })
        else
            env:Reload({ goodsId = item.goodsId, text = tostring(num), dojo = item.playerEquipment })
        end
        env:SetClickButtonAction(
                function(goodsId, uId)
                    GameUtils.ShowResultTips(cell.gameObject, goodsId, uId)
                end)
    end
    return cell
end

---OnGetStarRewardsByIndex
---三星奖励列表
---@param gridView SuperScrollView.LoopGridView
---@param index integer
function UIBattleEndRightPanel:OnGetStarRewardsByIndex(gridView, index)
    if index < 0 then return nil end
    local cell = gridView:NewListViewItem(StarRewardNodePrefabName)
    local reScale = cell.gameObject:GetComponent(typeof(ReverseScale))
    reScale:ResetScale()
    local goodNodeMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)
    if not IsNull(goodNodeMB) then
        if IsNull(goodNodeMB.Env) then
            goodNodeMB:Init()
        end
        ---@type GoodNodeMB
        local env = goodNodeMB.Env
        local item = self.starRewardList[index + 1]
        local num = self:CheckGoodsIdForSignNum(item.goodsId, item.num)
        if not IsNull(num) then
            num = string.format("x%s", num)
            env:Reload({ goodsId = item.goodsId, isShowNo = true, text = tostring(num), dojo = item.playerEquipment })
        else
            env:Reload({ goodsId = item.goodsId, text = tostring(num), dojo = item.playerEquipment })
        end
        env:SetClickButtonAction(
                function(goodsId, uId)
                    GameUtils.ShowResultTips(cell.gameObject, goodsId, uId)
                end)
    end
    return cell
end

---DataSort
---游戏物品数据排序
---@param target table
---@param low integer
---@param high integer
function UIBattleEndRightPanel:DataSort(target, low, high)
    local t = low or 1
    local r = high or #target
    local temp = target[t]

    if low < high then
        while (t < r) do
            while (self:CheckGoodsIdForDateSort(target[r].goodsId) >= self:CheckGoodsIdForDateSort(temp.goodsId) and t < r) do
                r = r - 1
            end
            target[t] = target[r]
            while (self:CheckGoodsIdForDateSort(target[t].goodsId) <= self:CheckGoodsIdForDateSort(temp.goodsId) and t < r) do
                t = t + 1
            end
            target[r] = target[t]
        end
        target[t] = temp
        self:DataSort(target, low, t - 1)
        self:DataSort(target, r + 1, high)
    end
end

---CheckGoodsIdForDateSort
---返回物品类型ID
---@param goodsId integer @ 物品Id
function UIBattleEndRightPanel:CheckGoodsIdForDateSort(goodsId)
    local idType = GoodsUtils.GetIdType(goodsId)
    local typeList = {
        [Constants.IDType.CharacterCard] = 1, -- 角色卡
        [Constants.IDType.Equipment] = 2, -- 装备
    }
    --- 3 游戏道具
    return typeList[idType] or 3
end

---CheckGoodsIdForSignNum
---判断物品类型返回显示类型
---@param goodsId integer @ 物品Id
---@param goodsNum integer @ 物品数量
function UIBattleEndRightPanel:CheckGoodsIdForSignNum(goodsId, goodsNum)
    local idType = GoodsUtils.GetIdType(goodsId)
    if idType == Constants.IDType.Equipment or idType == Constants.IDType.EquipmentCore then
       return
    end
    return goodsNum
end

return UIBattleEndRightPanel
